content.content:
 * context that holds a candidate, and with `fallBackWithoutContext` the first
 * without it, so that the refusal is reported where and as it is without it. A
 * candidate inferred by subtyping whose static args bind a type parameter to
 * a union is instantiated by the promotion instead, and is ranked on its
 * declared domain with the promotion's coercions uncounted. A call with no
 * most specific candidate is an error when coercions are in the tie, unless
 * the tie is a numeral's, which the numeral read as ZZ32 settles.
 *
 * A call with a numeral argument is the exception to the order of the
 * attempts: where the attempt by subtyping is kept and its most specific
 * candidate leaves a numeral at a parameter that fixes no type for it, the
 * candidates that only the numerals' own coercions reach are compared with
 * it, and one whose declared parameter types lie strictly below its own, by
 * subtyping, is the call's (numeralAttempt). Where two declarations are not
 * ordered so, the one that the numeral's default fits stays.
 */
def checkApplication(preCandidates: List[PreAppCandidate],
                     iargs: List[Expr],
                     context: Option[Type],
                     mOpName: Option[Op] = None,
                     fallBackWithoutContext: Boolean = false)
                    (implicit errorFactory: ApplicationErrorFactory)
                     : Option[List[AppCandidate]] =
  typedApplication(preCandidates, iargs, context, mOpName, fallBackWithoutContext).map(_._1)

/**
 * checkApplication with the call's type beside the candidates: the most
 * specific candidate's return type, or, for a tie among declarations without
 * static parameters that fit the call without coercion, in a family with no
 * declaration with static parameters, the intersection of the tied
 * candidates' return types. Such a tie arises where the argument's static
 * type sits between closed traits whose overlap other declarations cover;
 * the declaration that runs is below every tied one, and its return type
 * below each of theirs by the Return Type Rule.
 */
def typedApplication(preCandidates: List[PreAppCandidate],
                     iargs: List[Expr],
                     context: Option[Type],
                     mOpName: Option[Op],
                     fallBackWithoutContext: Boolean)
                    (implicit errorFactory: ApplicationErrorFactory)
                     : Option[(List[AppCandidate], Type)] = {

  // Check all the checkable args and make sure they all have types.
  val args = partitionArgs(iargs).getOrElse(return None)
  typedApplicationOfChecked(preCandidates, iargs, args, context, mOpName, fallBackWithoutContext, true)
}

/**
 * typedApplication over its args checked without an expected type. With
 * `retry`, a call that no attempt keeps is tried by the argument retry
 * before the attempts' fallback.
 */
def typedApplicationOfChecked(preCandidates: List[PreAppCandidate],
                              iargs: List[Expr],
                              args: List[Either[Expr, FnExpr]],
                              context: Option[Type],
                              mOpName: Option[Op],
                              fallBackWithoutContext: Boolean,
                              retry: Boolean)
                             (implicit errorFactory: ApplicationErrorFactory)
                              : Option[(List[AppCandidate], Type)] = {

  // A candidate, with its declaration's arrow when it is compared on its
  // declared domain, and whether the promotion instantiated it.
  type Ranked = (AppCandidate, Option[ArrowType], Boolean)
  type Attempt = List[(Either[AppCandidate, OverloadingError], Option[ArrowType], Boolean)]
  def moreSpecific(a: Ranked, b: Ranked) = moreSpecificCandidate(a._1, b._1, a._2, b._2, a._3, b._3)
  def isUnion(sarg: StaticArg) = sarg match {
    case STypeArg(_, false, _: UnionType) => true
    case _ => false
  }
  def generic(pc: PreAppCandidate) = getStaticParams(pc.arrow).exists(!_.isLifted)

  // Filter the overloadings that are applicable, by subtyping or with
  // coercion. A candidate without static parameters is checked alike in
  // every attempt, so it is checked once.
  val plain = scala.collection.mutable.Map[Int, (Either[AppCandidate, OverloadingError], Option[ArrowType], Boolean)]()
  def applicable(ctx: Option[Type], coerce: Boolean): Attempt = preCandidates.zipWithIndex.map { case (pc, i) =>
    if (getStaticParams(pc.arrow).isEmpty)
      plain.getOrElseUpdate(i, (checkApplicable(pc, ctx, args, mOpName, coerce), None, false))
    else checkApplicable(pc, ctx, args, mOpName, coerce) match {
      case Left(c) if !coerce && c.sargs.exists(isUnion) =>
        checkApplicable(pc, ctx, args, mOpName, false, Some(c.sargs.filter(!_.isLifted))) match {
          case Left(promoted) => (Left(promoted), Some(pc.arrow), true)
          case _ => (Left(c), None, false)
        }
      case Left(c) if coerce && generic(pc) => (Left(c), Some(pc.arrow), false)
      case e => (e, None, false)
    }
  }
  def candidatesOf(es: Attempt): List[Ranked] = es.collect { case (Left(c), d, p) => (c, d, p) }
  // A coercion the call needs, not one the promotion introduced.
  def counted(c: Ranked) = !c._3 && c._1.args.exists(NumeralConversion.counts)
  // An attempt by subtyping holds the candidates that fit the call without a
  // coercion it needs; an attempt with coercion holds all it finds.
  def holds(es: Attempt, coerce: Boolean) =
    if (coerce) candidatesOf(es).nonEmpty else candidatesOf(es).exists(!counted(_))
  def paramTypes(c: Ranked) = zipWithDomain(c._1.args, c._1.arrow.getDomain).map(_._2)
  def sameTypes(a: List[Type], b: List[Type]) =
    a.size == b.size && a.zip(b).forall(p => Formula.isTrue(analyzer.equivalent(p._1, p._2)))
  // The candidates no other candidate is more specific than.
  def minimal(cs: List[Ranked]) = new PartialOrder[Ranked](cs, moreSpecific).minimal
  val groundFamily = preCandidates.forall(pc => getStaticParams(pc.arrow).isEmpty)
  // The type of a tie among declarations without static parameters that fit
  // the call as it is, in a family without static parameters.
  def tieType(top: List[Ranked]): Option[Type] =
    if (groundFamily && top.size > 1 && !top.exists(counted) &&
        top.forall(c => c._2.isEmpty && !c._3 && c._1.sargs.isEmpty) &&
        !top.forall(c => sameTypes(paramTypes(c), paramTypes(top.head))))
      Some(analyzer.meet(top.map(_._1.arrow.getRange)))
    else None
  // The first candidate no other is more specific than, or the first where
  // each has one more specific.
  def callType(cs: List[Ranked]): Type = {
    val top = minimal(cs)
    (if (groundFamily) tieType(top) else None).getOrElse(top.headOption.getOrElse(cs.head)._1.arrow.getRange)
  }
  def kept(es: Attempt, coerce: Boolean) = holds(es, coerce) && context.forall(c =>
    coercions.substitutableFor(callType(candidatesOf(es)), c))
  // Each attempt: whether it is given the context, whether it coerces, and
  // the attempt itself.
  val attempts: List[(Boolean, Boolean, () => Attempt)] =
    if (context.isDefined)
      List((false, false, () => applicable(None, false)), (true, false, () => applicable(context, false)),
           (true, true, () => applicable(context, true)), (false, true, () => applicable(None, true)))
    else List((true, false, () => applicable(None, false)), (true, true, () => applicable(None, true)))
  val tried = attempts.to(LazyList).map { case (withContext, coerce, a) => (withContext, coerce, a()) }
  val keptAttempt = tried.find { case (_, coerce, a) => kept(a, coerce) }
  if (keptAttempt.isEmpty && retry)
    retypedApplication(preCandidates, iargs, args, context, mOpName, fallBackWithoutContext).
      foreach(r => return Some(r))
  val es = keptAttempt.map(_._3).getOrElse {
    // No attempt is kept: of the attempts with the context, or for a call
    // written f(x) of those without it, the first that holds a candidate,
    // whatever its result, and otherwise the first.
    val from = tried.filter(_._1 != (fallBackWithoutContext && context.isDefined))
    from.find { case (_, coerce, a) => holds(a, coerce) }.getOrElse(from.head)._3
  }

  // A call with a numeral argument, whose attempt by subtyping is kept: the
  // candidates that only the numerals' own coercions reach, each strictly
  // below, on its declared parameter types and by subtyping, every most
  // specific candidate of the attempt by subtyping. They are sought only
  // where such a candidate has a numeral at a parameter whose type is not
  // the numeral's default type: at its default type no other declaration
  // lies below by a numeral's coercion.
  val numeralAt = args.zipWithIndex.collect { case (Left(e), i) if NumeralConversion.isNumeral(e) => (i, e) }
  def atDefaultType(e: Expr, t: Type) = t match {
    case tt: TraitType => tt.getArgs.isEmpty && NumeralConversion.defaultName(e).exists(_ == tt.getName.getText)
    case _ => false
  }
  def onlyNumerals(c: Ranked) = c._1.args.size == args.size && c._1.args.zip(args).forall {
    case (a, Left(e)) => !NumeralConversion.counts(a) || NumeralConversion.isNumeral(e)
    case _ => true
  }
  def declared(c: Ranked) = c._2.getOrElse(c._1.arrow)
  def numeralAttempt: Option[Attempt] = keptAttempt match {
    case Some((withContext, false, a)) if numeralAt.nonEmpty =>
      val heads = minimal(candidatesOf(a).filter(!counted(_)))
      def open(h: Ranked) = {
        val ps = paramTypes(h)
        ps.size == args.size && numeralAt.exists { case (i, e) => !atDefaultType(e, ps(i)) }
      }
      if (!heads.exists(open)) None
      else {
        val below = applicable(if (withContext) context else None, true).filter {
          case (Left(c), d, p) =>
            val r = (c, d, p)
            counted(r) && onlyNumerals(r) &&
            heads.forall(h => coercions.moreSpecificDeclared(declared(r), declared(h)))
          case _ => false
        }
        if (below.isEmpty ||
            !context.forall(t => coercions.substitutableFor(callType(candidatesOf(below)), t))) None
        else Some(below)
      }
    case _ => None
  }

  // The call's candidates from an attempt, the most specific at the head.
  // With `quiet`, an attempt that does not resolve to one candidate signals
  // nothing and gives none.
  def resolved(es: Attempt, quiet: Boolean): Option[(List[AppCandidate], Type)] = {
  val candidates = candidatesOf(es)
  val overloadingErrors = es.collect { case (Right(e), _, _) => e }

  // If there were no candidates, report errors, and each numeral outside
  // the range of a parameter type that would take it.
  if (candidates.isEmpty) {
    if (quiet) return None
    errors.signal(errorFactory.makeApplicationError(overloadingErrors))
    signalNumeralRanges(preCandidates, args)
    return None
  }

  // Sort the arrows and instantiations to find the statically most
  // applicable. Then update each candidate's Overloading node. The sort and
  // the minimal candidates below read one order.
  val order = new PartialOrder[Ranked](candidates, moreSpecific)
  val sorted = order.linear

  // An overloading more specific than every candidate, whose size the call
  // does not fix, makes the call an error.
  val unfixed = overloadingErrors.filter {
    case NoContextError(_, _, Some(u)) => candidates.forall(c => moreSpecificCandidate(u, c._1, None, c._2, false, c._3))
    case _ => false
  }
  if (!unfixed.isEmpty) {
    if (quiet) return None
    errors.signal(errorFactory.makeApplicationError(unfixed))
    return None
  }

  // Ensure that the head is the most specific: the one candidate no other
  // is more specific than.
  val top = order.minimal

  // A tie of a call with a numeral argument, whether the tied candidates
  // differ only where the argument is a numeral or elsewhere too:
  // each numeral is read as its default, ZZ32 (ZZ64 or ZZ by magnitude) or
  // RR64 with a radix point, and the call
  // resolves as an argument of that type would, over every candidate: of
  // those the readings fit, the ones they fit without coercion first. At a
  // position whose declared type is a bare type parameter, a reading fits a
  // candidate compared on its declared arrow by that parameter's bound.
  def numeralTie(): Option[Ranked] = {
    val exprs = args.map(_.left.toOption)
    val n = exprs.size
    if (top.exists(c => paramTypes(c).size != n)) return None
    if (!exprs.exists(_.exists(isNumeral))) return None
    val readings = (0 until n).toList.flatMap(i => exprs(i).filter(isNumeral).map(e => (i, numeralReading(List(e)))))
    if (readings.exists(_._2.isEmpty)) return None
    // The types a reading must fit at position i of a candidate.
    def targets(c: Ranked, i: Int, r: Type): List[Type] = {
      val bare = c._2.flatMap { d =>
        val sps = getStaticParams(d).filter(sp => !sp.isLifted && sp.getKind.isInstanceOf[KindType])
        zipWithDomain(args, d.getDomain).lift(i).map(_._2) match {
          case Some(v: VarType) => sps.find(_.getName == v.getName).map { sp =>
            object subst extends Walker {
              override def walk(node: Any): Any = node match {
                case w: VarType if w.getName == v.getName => r
                case _ => super.walk(node)
              }
            }
            toListFromImmutable(sp.getExtendsClause).map(b => subst(b).asInstanceOf[Type])
          }
          case _ => None
        }
      }
      bare.getOrElse(List(paramTypes(c)(i)))
    }
    def fitsBy(c: Ranked, rel: (Type, Type) => Boolean) = readings.forall { case (i, r) =>
      targets(c, i, r.get).forall(t => rel(r.get, t)) }
    val fits = candidates.filter(fitsBy(_, coercions.substitutableFor))
    val unconverted = fits.filter(fitsBy(_, (r, t) => isSubtype(r, t)))
    val among = if (unconverted.nonEmpty) unconverted else fits
    among.filter(c => !among.exists(d => !(d eq c) && moreSpecific(d, c))) match {
      case List(c) => Some(c)
      case _ => None
    }
  }

  // An argument's type with self's type read as its trait's alone.
  def traitOfSelf(t: Type): Type = {
    object named extends Walker {
      override def walk(node: Any): Any = node match {
        case s: TraitSelfType => s.getNamed
        case _ => super.walk(node)
      }
    }
    named(t).asInstanceOf[Type]
  }
  // Whether the candidate takes each argument with self read as its trait.
  def takesSelfAtTrait(c: Ranked) = {
    val ps = paramTypes(c)
    ps.size == c._1.args.size &&
    c._1.args.zip(ps).forall { case (a, p) => getType(a).exists(t => isSubtype(traitOfSelf(t), p)) }
  }

  val head: Option[Ranked] =
    if (top.size == 1) top.headOption
    // A tie among candidates that fit the call as it is, or among candidates
    // with one parameter type, keeps the sort's head; a tie that self's type
    // makes keeps the head of those that take self at its trait's type. In a
    // trait whose comprises clause lists types, self has the trait's type met
    // with theirs, so a listed type's declaration fits it as the trait's own
    // does; the trait's own takes the value that the compiled call passes,
    // and dispatch reaches the listed type's.
    else if (top.isEmpty || !top.exists(counted) ||
             top.forall(c => sameTypes(paramTypes(c), paramTypes(top.head)))) {
      val atTrait = top.filter(takesSelfAtTrait)
      if (atTrait.nonEmpty && atTrait.size < top.size) sorted.find(c => atTrait.exists(_ eq c))
      else sorted.headOption
    }
    else numeralTie().orElse {
      if (!quiet) signalAmbiguity(top.map(c => c._2.getOrElse(c._1.arrow)), args)
      return None
    }
  Some((head.toList.map(_._1) ++ sorted.filterNot(c => head.exists(_ eq c)).map(_._1),
        tieType(top).getOrElse(head.getOrElse(sorted.head)._1.arrow.getRange)))
  }

  numeralAttempt.flatMap(resolved(_, true)).orElse(resolved(es, false))
}

/**
 * The argument retry, for a call that no attempt keeps, an argument of
 * which is itself a call whose static args it inferred with no expected
 * type. Each candidate in turn: each such argument is checked again with
 * the candidate's parameter type at its position as its expected type, that
 * type instantiated, where the candidate has static parameters, by the other
 * arguments (writesStaticArgs) and the call's expected type alone; the call is then checked
 * against that candidate alone, and the candidate counts when the call's
 * type converts to the expected type. Of the candidates that count, the one
 * more specific on its declared parameter types than every other is kept,
 * with its arguments. Otherwise the call is refused as it was.
 */
private def retypedApplication(preCandidates: List[PreAppCandidate],
                               iargs: List[Expr],
                               args: List[Either[Expr, FnExpr]],

class CoercionOracle(traits: TraitTable,
                     current: CompilationUnitIndex)
                    (implicit analyzer: TypeAnalyzer) {

  /** A coercion index and its arrow type with lifted params instantiated. */
  type LiftedCoercion = (Coercion, ArrowType, ArrowType)

  /**
   * Create the Id for an invocation of a coercion to trait U. If the trait's
   * name is Oof which is an imported alias of Foo from API A, then the coercion
   * name will include "Foo" instead of "Oof". In any case, if the trait was
   * imported explicitly (e.g. not via ellipsis), this coercion name will be
   * qualified.
   */
  def makeCoercionId(u: TraitType): Id = {
    val realTraitName = getRealName(u.getName, toListFromImmutable(current.ast.getImports))
    NF.makeLiftedCoercionId(NU.getSpan(u), realTraitName.asInstanceOf[Id])
  }

  /**
   * Get the most specific type out of a set of types under the `moreSpecific`
   * relation.
   */
  def mostSpecific(cs: Set[Type]): Option[Type] = {
    if (cs.isEmpty) {
      bug("Attempt to find the most specific type in an empty set")
    }
    else {
      var result: Option[Type] = None
      for (c <- cs ; if result.isEmpty || moreSpecific(c, result.get)) {
        result = Some(c)
      }
      result
    }
  }

  /** The `moreSpecific` relation; no less specific and unequal. */
  def moreSpecific(t: Type, u: Type): Boolean =
    noLessSpecific(t, u) && !isTrue(analyzer.equivalent(t, u))

  /**
   * The `moreSpecific` relation on two declarations' arrows, compared on their
   * declared, quantified domains by subtyping, as the overloading oracle
   * compares declarations.
   */
  def moreSpecificDeclared(f: ArrowType, g: ArrowType): Boolean = {
    val oracle = new OverloadingOracle()(analyzer)
    oracle.lteq(f, g) && !oracle.lteq(g, f)
  }

  /** The `noLessSpecific` relation. */
  def noLessSpecific(t: Type, u: Type): Boolean =
    isTrue(analyzer.subtype(t, u)) ||
      (analyzer.definitelyExcludes(t, u) && coercesTo(t, u) && rejects(t, u))

  /** Determines if T rejects U. */
  def rejects(t: Type, u: Type): Boolean =
    getCoercionsTo(t).forall(ca => analyzer.definitelyExcludes(ca._2.getDomain, u))

  /** The set of all arrow types for coercions from types T to U. */
  def getCoercionsTo(uu: Type): Set[LiftedCoercion] = {
    val u =
      if (uu.isInstanceOf[TraitSelfType] &&
          uu.asInstanceOf[TraitSelfType].getNamed.isInstanceOf[TraitType])
        uu.asInstanceOf[TraitSelfType].getNamed.asInstanceOf[TraitType]
      else uu

    if (!u.isInstanceOf[TraitType]) return Set()

    // Get name and possible static args out of the type.
    val STraitType(_, name, sargs, _) = u

    // Get all the coercions from the type U.
    val coercions = toOption(traits.typeCons(name)) match {
      case Some(ti:TraitIndex) => toSet(ti.coercions)
      case None => Set()
    }

    // Get the instantiated coercion arrow.
    def instantiateArrow(c: Coercion): Option[LiftedCoercion] = {
      makeArrowFromFunctional(c).flatMap(arrow =>
        staticInstantiation(sargs,
                            arrow,
                            applyLifted = true,
                            applyUnlifted = false)
          .map(instArrow => (c, instArrow.asInstanceOf[ArrowType], arrow)))
    }

    // Get all the arrows that were found.
    coercions.flatMap(instantiateArrow)
  }

  /** Determines if T is substitutable for U. */
  def substitutableFor(t: Type, u: Type): Boolean =
    isTrue(analyzer.subtype(t, u)) || coercesTo(t, u)

  /**
   * The trait types without static parameters that define a coercion from T or
   * a supertype of T: the types T can be coerced to, found from T where
   * `getCoercionsTo` goes from the target.
   */
  def getCoercionTargetsFrom(t: Type): List[TraitType] =
    traits.coercingTraits.filter(_.staticParameters.isEmpty).flatMap { ti =>
      val arrows = toSet(ti.coercions).toList.flatMap(c => makeArrowFromFunctional(c))
      val sources = arrows.filter(a => !hasStaticParams(a)).map(_.getDomain)
      // A numeral's type reaches a coercion generic over its four numbers.
      def generic = Types.isNumeralType(t) &&
        arrows.exists(a => hasStaticParams(a) && Types.isNumeralType(a.getDomain) &&
                           inferStaticParams(a, t, None).isDefined)
      if (sources.exists(s => isTrue(analyzer.subtype(t, s))) || generic) toOption(ti.typeOfSelf).flatMap(getTraitType)
      else None
    }

  /**
   * Determine if T is substitutable for U. If T <: U, then return Some(None).
   * If T ~~> U and expr given, then return Some(Some(c)) where c is the
   * coercion of expr to type U. If T ~~> U and expr not given, then return
   * Some(None). Otherwise, return None.
   */
  def checkSubstitutable(t: Type,
                         u: Type,
                         expr: Option[Expr])
                         : Option[Option[CoercionInvocation]] = {
    if (isTrue(analyzer.subtype(t, u)))
      Some(None)
    else
      checkCoercion(t, u, expr)
  }

  /** Determines if T ~~> U. */
  def coercesTo(t: Type, u: Type): Boolean = checkCoercion(t, u, None).isSome

  /**
   * The prefix minus of the type U applied to an expression of type U, checked;
   * the type checker that owns this oracle sets it.
   */
  var negator: (Expr, Type) => Option[Expr] = (_, _) => None

  /**
   * Determines if e:T ~~> U and if so returns the FnRefs for that coercion.
   * A numeral outside the range of U, one of the library's bounded number
   * types, has none. A numeral has no sign: at a program's own type a
   * negative constant is the type's own prefix minus on the coercion of the
   * numeral as written, and a folded static expression reaches no coercion
   * from the numeral types (its default does, through defaultFits).
   */
  def buildCoercion(e: Expr, u: Type): Option[Expr] =
    if (NumeralConversion.outOfRange(e, u).isDefined) None
    else (e, u) match {
      // A tuple that holds a numeral converts element by element where it
      // stands: no numeral value exists to bind to a variable at run time.
      case (STupleExpr(SExprInfo(span, paren, _), es, None, Nil, inApp), STupleType(_, us, None, Nil))
          if es.size == us.size && es.exists(NumeralConversion.isNumeral) =>
        val nes = es.zip(us).map { case (x, t) =>
          if (getType(x).exists(xt => isTrue(analyzer.subtype(xt, t)))) Some(x) else buildCoercion(x, t) }
        if (nes.forall(_.isDefined)) Some(STupleExpr(SExprInfo(span, paren, Some(u)), nes.map(_.get), None, Nil, inApp))
        else None
      case _ => buildNonTuple(e, u)
    }

  private def buildNonTuple(e: Expr, u: Type): Option[Expr] =

